contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address s, uint256 v1, uint256 v2) public {
        require(s != address(0));
        require(v1 > 0 && v2 > 0 && v2 != v1);
        c.approve(s, v1); if (__ESBMC_reverted()) return;
        bool ok = c.approve(s, v2); if (__ESBMC_reverted()) return;
        assert(!ok && c.allowance(address(this), s) == v1);
    }
    receive() external payable {}
}

