        c = new NewIntelTechMedia();
    }

    function _run(address s, uint256 v1, uint256 v2) internal {
        vm.assume(s != address(0));
        vm.assume(v1 > 0 && v2 > 0 && v2 != v1);
        try c.approve(s, v1) {} catch { return; }
        bool ok;
        try c.approve(s, v2) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(!ok && c.allowance(address(this), s) == v1);
    }

    function testFuzz_run(address s, uint256 v1, uint256 v2) public {
